1	/**
2	 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
5	 */
6	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
7	import { emit } from "@/lib/event-bus";
8	import { hashToken, randomToken } from "@/lib/hash";
9	import { assertCan } from "@/lib/permissions";
10	import { consumeRateLimit } from "@/lib/rate-limit";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as invitationRepo from "@/server/repositories/invitation-repository";
13	import * as memberRepo from "@/server/repositories/member-repository";
14	import * as orgRepo from "@/server/repositories/organization-repository";
15	import { toIsoTimestamp } from "@/types/common";
16	import { envelope, orgResource, requireFound } from "./_support";
17	import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
18	import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
19	import type { InvitationId, UserId } from "@/types/common";
20	import type { Actor, Invitation, Member } from "@/types/member";
21	
22	/** Token bucket protecting the invite mailer from being used as a spam relay. */
23	const INVITE_BUCKET = "member:invite";
24	
25	/** Default validity of a freshly minted invitation, in days. */
26	const DEFAULT_EXPIRY_DAYS = 14;
27	
28	export async function inviteMember(
29	  actor: Actor,
30	  input: InviteMemberInput,
31	): Promise<Invitation> {
32	  const [invitation] = await inviteMembers(actor, {
33	    orgId: input.orgId,
34	    invites: [{ email: input.email, role: input.role }],
35	  });
36	
37	  if (!invitation) throw new Error("Invitation was not created");
38	  return invitation;
39	}
40	
41	/**
42	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
43	 * five people into a plan with three free seats must fail as a batch rather
44	 * than half-succeeding — and the rate limit is charged per invite.
45	 */
46	export async function inviteMembers(
47	  actor: Actor,
48	  input: InviteMembersInput,
49	): Promise<readonly Invitation[]> {
50	  assertOrgScope(actor, input.orgId);
51	  assertCan(actor, "member:invite", orgResource(input.orgId));
52	
53	  const verdict = await consumeRateLimit(
54	    input.orgId,
55	    INVITE_BUCKET,
56	    input.invites.length,
57	  );
58	  if (!verdict.allowed) {
59	    throw new Error(
60	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
61	    );
62	  }
63	
64	  const org = requireFound(
65	    await orgRepo.findOrgById(input.orgId),
66	    "Organization",
67	    input.orgId,
68	  );
69	
70	  const seatsUsed =
71	    (await memberRepo.countActiveMembers(input.orgId)) +
72	    (await invitationRepo.countPendingInvitations(input.orgId));
73	
74	  if (
75	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
76	  ) {
77	    const limits = getPlanLimits(org.plan);
78	    throw new Error(
79	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
80	    );
81	  }
82	
83	  const invitations: Invitation[] = [];
84	
85	  for (const invite of input.invites) {
86	    const token = randomToken(32);
87	    const invitation = await invitationRepo.insertInvitation(
88	      input.orgId,
89	      {
90	        orgId: input.orgId,
91	        email: invite.email,
92	        role: invite.role,
93	        expiresInDays: DEFAULT_EXPIRY_DAYS,
94	      },
95	      actor.userId,
96	      hashToken(token),
97	    );
98	
99	    invitations.push(invitation);
100	
101	    await emit("member.invited", {
102	      orgId: input.orgId,
103	      actorId: actor.userId,
104	      occurredAt: invitation.createdAt,
105	      email: invite.email,
